import { Geist, Geist_Mono } from "next/font/google";
import "./globals.css";
import ScrollLock from "./scroll-lock"; // <-- thêm dòng này

const geistSans = Geist({ variable: "--font-geist-sans", subsets: ["latin"] });
const geistMono = Geist_Mono({ variable: "--font-geist-mono", subsets: ["latin"] });

export const metadata: Metadata = {
  title: "AskThemAll AI",
  description: "Generated by create next app",
};

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <ClerkProvider>
      <html lang="vi" className="h-dvh">{/* KHÔNG khóa cuộn ở đây */}
        <body
          className={`${geistSans.variable} ${geistMono.variable} antialiased min-h-dvh overflow-y-auto bg-[#FCF8EC]`}
        >
          {children}
          <ScrollLock /> {/* Bật/tắt khóa cuộn theo route */}
        </body>
      </html>
    </ClerkProvider>
  );
}
